import{_ as r,a,o as t,a6 as d}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Place Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-place-order","title":"Place Order","description":"Finalise a fully prepared draft cart into a real order.","query":"mutation PlaceOrder($input: createAdminPlaceOrderInput!) {\\n  createAdminPlaceOrder(input: $input) {\\n    adminPlaceOrder {\\n      orderId\\n      incrementId\\n      customerId\\n      grandTotal\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"cartId\\": 314\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminPlaceOrder\\": {\\n      \\"adminPlaceOrder\\": {\\n        \\"orderId\\": 1284,\\n        \\"incrementId\\": \\"1284\\",\\n        \\"customerId\\": 19,\\n        \\"grandTotal\\": 110,\\n        \\"success\\": true,\\n        \\"message\\": \\"Order placed successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/carts/place-order.md","filePath":"api/graphql-api/admin/sales/carts/place-order.md","lastUpdated":1787290888000}'),n={name:"api/graphql-api/admin/sales/carts/place-order.md"};function o(s,e,i,c,l,p){return t(),a("div",null,e[0]||(e[0]=[d('<h1 id="place-order" tabindex="-1">Place Order <a class="header-anchor" href="#place-order" aria-label="Permalink to &quot;Place Order&quot;">​</a></h1><p>Finalises a fully prepared draft cart into a real order — the same flow as the admin Create-Order screen&#39;s place-order step. Items, addresses, shipping and payment must already be set on the draft cart.</p><h3 id="select-result-fields-not-id" tabindex="-1">Select result fields, not <code>id</code> <a class="header-anchor" href="#select-result-fields-not-id" aria-label="Permalink to &quot;Select result fields, not `id`&quot;">​</a></h3><p>Select <code>orderId</code> (the new order&#39;s id), <code>incrementId</code>, <code>customerId</code>, <code>grandTotal</code>, <code>success</code>, <code>message</code>. Do <strong>not</strong> select <code>id</code> (or <code>_id</code>): this is an action result with no addressable record, so the auto-generated IRI field is <code>null</code> and selecting it errors out the whole payload.</p><p><strong>Prerequisites</strong> — The example uses an illustrative cart id. Admin cart endpoints only operate on <strong>draft carts</strong> (<code>is_active=0</code>) — storefront carts are rejected. Create a draft cart first with the <a href="./../../customers/create-draft-cart.html"><code>createAdminDraftCart</code></a> mutation and use the returned <code>cartId</code>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminPlaceOrder(input)</code></td><td>Mutation</td><td>Finalise a draft cart into an order</td></tr></tbody></table><h2 id="sequence-errors" tabindex="-1">Sequence (errors[]) <a class="header-anchor" href="#sequence-errors" aria-label="Permalink to &quot;Sequence (errors[])&quot;">​</a></h2><p>Each missing step surfaces as a distinct GraphQL error (REST counterpart in parentheses):</p><ul><li>Cart empty (409)</li><li>Cart total below the store&#39;s minimum order amount (422)</li><li>Addresses missing (409)</li><li>Shipping method missing (409)</li><li>Payment method missing (409)</li><li>Payment method not in <code>[cashondelivery, moneytransfer]</code> (422)</li></ul>',10)]))}const h=r(n,[["render",o]]);export{m as __pageData,h as default};
